// =============================================================================
// UTILIDADES COMUNES DE LOS NODOS DE LA «VENTA DIGITAL DE RUBÉN» (prefijo `cn`)
// =============================================================================
// El constructor las pega entre la librería (`rr.js`, y las `cm*` en los nodos que las piden) y el código de cada nodo. JavaScript plano: sin `require`, `URL`,
// `Buffer` ni `crypto`, y nada de red. Lo que se lee de otro nodo se lee POR NOMBRE y solo si corrió (`isExecuted`): un nodo que no corrió no se lee con `.item`.
// Ningún nodo lee por nombre algo que corre más de una vez en la ejecución (no hay ciclos): `first()` es siempre «el único».

// El nodo `nombre` si existe Y corrió en esta ejecución; si no, null. En un JSON que no lo trae (el de producción no tiene «Entrada de prueba») `$()` lanza.
function cnNodo(nombre) {
  try {
    const n = $(nombre);
    return n && n.isExecuted ? n : null;
  } catch (e) {
    return null;
  }
}
function cnPrimero(nombre) {
  const n = cnNodo(nombre);
  if (!n) return null;
  try {
    const i = n.first();
    return i && i.json ? i.json : null;
  } catch (e) {
    return null;
  }
}
function cnTodos(nombre) {
  const n = cnNodo(nombre);
  if (!n) return [];
  try {
    return n.all().map((i) => (i && i.json) || {});
  } catch (e) {
    return [];
  }
}
function cnCfg() {
  return cnPrimero('Config del negocio') || {};
}
function cnDigitos(v) {
  return String(v === undefined || v === null ? '' : v).replace(/\D/g, '');
}
function cnRecorte(t, max) {
  const s = String(t === undefined || t === null ? '' : t);
  return s.length > max ? s.slice(0, max - 1).trimEnd() + '…' : s;
}
// El texto de una respuesta de Gemini (generateContent, o el nodo de LangChain con `simplify`). '' si vino un error o algo que no se reconoce.
function cnTextoDeGemini(j) {
  if (!j || typeof j !== 'object' || j.error) return '';
  const partes = (c) => (c && Array.isArray(c.parts))
    ? c.parts.map((p) => (p && typeof p.text === 'string') ? p.text : '').join('\n') : '';
  if (typeof j.content === 'string') return j.content;
  const c1 = partes(j.content);
  if (c1) return c1;
  const cand = Array.isArray(j.candidates) ? j.candidates[0] : null;
  const c2 = cand ? partes(cand.content) : '';
  if (c2) return c2;
  for (const k of ['text', 'transcription', 'output', 'response']) {
    if (typeof j[k] === 'string' && j[k].trim()) return j[k];
  }
  return '';
}
// El objeto JSON que Gemini devolvió como texto; null si no es un objeto.
function cnJsonDeGemini(j) {
  const t = cnTextoDeGemini(j).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  if (!t) return null;
  const m = /\{[\s\S]*\}/.exec(t);
  try {
    const o = JSON.parse(m ? m[0] : t);
    return o && typeof o === 'object' && !Array.isArray(o) ? o : null;
  } catch (e) {
    return null;
  }
}
// La clave de la ficha es el teléfono de origen y solo dígitos: nunca un nombre que toque el prototipo.
function cnClaveValida(from) {
  return /^\d{6,20}$/.test(String(from || ''));
}
// Las fichas de los teléfonos (`staticData.global.rroca`). Un nodo que SOLO LEE no escribe nada en los datos estáticos. Los que escriben (con `escribir` verdadero) crean el mapa si falta.
function cnMapaDeFichas(escribir) {
  let sd = null;
  try { sd = $getWorkflowStaticData('global'); } catch (e) { sd = null; }
  if (!sd) return { sd: null, mapa: {} };
  const valido = sd.rroca && typeof sd.rroca === 'object' && !Array.isArray(sd.rroca);
  if (!valido) {
    if (escribir !== true) return { sd: sd, mapa: {} };
    sd.rroca = {};
  }
  return { sd: sd, mapa: sd.rroca };
}
function cnFichaDe(mapa, from) {
  return cnClaveValida(from) && Object.prototype.hasOwnProperty.call(mapa, from) ? mapa[from] : null;
}
// La atención del teléfono: lo que devolvió la ingesta del entrante si lo trae, y si no, lo que dijo `configuracionFlujo`. Ante la duda, normal.
function cnAtencion(rIngesta, cfg) {
  const a = rIngesta && typeof rIngesta === 'object' && rIngesta.atencion && typeof rIngesta.atencion === 'object'
    ? rIngesta.atencion : null;
  const estados = ['normal', 'operador', 'bloqueado'];
  const estado = a && estados.indexOf(a.estado) >= 0 ? a.estado
    : (estados.indexOf(cfg.atencionEstado) >= 0 ? cfg.atencionEstado : 'normal');
  const avisarIngesta = rIngesta && typeof rIngesta === 'object' ? rIngesta.avisarRecepcion : '';
  const avisarCfg = a && a.avisarRecepcion !== undefined ? a.avisarRecepcion : cfg.atencionAvisarRecepcion;
  const avisar = ['operador', 'bloqueado'].indexOf(avisarIngesta || avisarCfg) >= 0 ? (avisarIngesta || avisarCfg) : '';
  return {
    estado: estado,
    avisar: avisar,
    mensajeFijo: String((a && a.mensajeFijo) || cfg.atencionMensajeFijo || '').trim(),
    respuestas: Number(a && a.respuestasEnVentana !== undefined ? a.respuestasEnVentana : cfg.atencionRespuestas) || 0,
    venceEn: String((a && a.ventanaVenceEn) || cfg.atencionVenceEn || ''),
  };
}

// CARGA DE ENTRADA: deja la entrada en UNA forma, venga de donde venga, y FILTRA los eventos: solo pasan las cargas con `messages`, sin `statuses` y del número esperado
// (`phone_number_id` = `phoneNumberIdEsperado` de «Config base»). Los acuses de estado y los mensajes de otro número se descartan AQUÍ, antes de traer la configuración.
//
// Formas que acepta:
//   1. el disparador de WhatsApp: {messages, metadata, contacts} en la raíz;
//   2. un Webhook: lo mismo dentro de `body`;
//   3. la carga completa de la Cloud API: {entry:[{changes:[{value:{...}}]}]}, en la raíz o dentro de `body`;
//   4. la del receptor: si CORRIÓ «Entrega del receptor», el evento es su `body.value` (y si `body.field` viene, tiene que ser `messages`: otro campo —un cambio de plantilla, de calidad— no es un mensaje). Ese nodo manda
//      sobre las otras tres: lo que pasa por «Verificar firma con el receptor» ya no es el evento sino su veredicto, y NUNCA se lee como un mensaje.
//
// EL MODO PRUEBA NO SE LEE DE LA CARGA. Solo lo activa el nodo «Entrada de prueba» (un Webhook que el JSON de producción NO tiene): se pregunta si ese nodo corrió y se
// lee SU cuerpo, con `=== true`. Una carga de WhatsApp con `modoPrueba` adentro —en la raíz, en el mensaje o en un texto— no lo activa jamás.
function cnValorDeMeta(c) {
  if (!c || typeof c !== 'object') return null;
  if (Array.isArray(c.messages) || Array.isArray(c.statuses)) return c;
  const entradas = Array.isArray(c.entry) ? c.entry : [];
  for (const e of entradas) {
    const cambios = e && Array.isArray(e.changes) ? e.changes : [];
    for (const ch of cambios) {
      const v = ch && ch.value;
      if (v && typeof v === 'object' && (Array.isArray(v.messages) || Array.isArray(v.statuses))) return v;
    }
  }
  return null;
}

function cnPrueba() {
  const w = cnPrimero('Entrada de prueba');
  const b = w && w.body && typeof w.body === 'object' ? w.body : null;
  if (!b || b.modoPrueba !== true) return null;
  return {
    modoPrueba: true,
    telefonoDePrueba: cnDigitos(b.telefonoDePrueba),
    enviarDeVerdad: b.enviarDeVerdad === true,
  };
}

const ahoraMs = Date.now();
const prueba = cnPrueba();
const esperado = String((cnPrimero('Config base') || {}).phoneNumberIdEsperado || '');
const receptor = cnPrimero('Entrega del receptor');
const cuerpoReceptor = receptor && receptor.body && typeof receptor.body === 'object' ? receptor.body : {};
const salida = [];
for (const it of $input.all()) {
  const j = (it && it.json) || {};
  const b = !receptor && j.body && typeof j.body === 'object' ? j.body : null;
  const v = receptor
    ? (cuerpoReceptor.value && typeof cuerpoReceptor.value === 'object' && (cuerpoReceptor.field === undefined || cuerpoReceptor.field === 'messages') ? cnValorDeMeta(cuerpoReceptor.value) : null)
    : (cnValorDeMeta(j) || cnValorDeMeta(b));
  const metadata = (v && v.metadata) || (j.metadata) || (b && b.metadata) || {};
  const messages = v && Array.isArray(v.messages) ? v.messages : [];
  const statuses = v && Array.isArray(v.statuses) ? v.statuses : [];
  const phoneNumberId = String(metadata.phone_number_id || '');
  // El filtro de eventos: nada de acuses, nada sin mensaje y nada de otro número.
  if (!messages.length || statuses.length || esperado === '' || phoneNumberId !== esperado) continue;
  salida.push({ json: {
    messaging_product: 'whatsapp',
    metadata: metadata,
    contacts: v && Array.isArray(v.contacts) ? v.contacts : [],
    messages: messages,
    statuses: statuses,
    phoneNumberId: phoneNumberId,
    ahoraMs: ahoraMs,
    prueba: prueba,
  } });
}
return salida;

